{
  "reading_questions": [
    {
      "anchor": "山公以器重朝望年踰七十猶知管時任",
      "question": "此句言山濤年逾七十仍掌管要職，但未說明具體職位與時間，讀者難以判斷其政治地位與實際權力。",
      "why_unclear": "正文僅以『器重朝望』概括，未交代官職、任期及具體政績，無法理解其『知管時任』的具體內涵。",
      "clues": "劉注引虞預晉書載山濤『累遷吏部尚書、僕射、太子少傅、司徒』，並言其年七十九薨；余嘉錫箋疏引程炎震考證，推測此事在咸寧太康間，濤為右僕射掌選。",
      "impact": "若查清山濤此時的具體官職與選官權力，可更準確理解謠言中『大牛』比喻的所指，以及王濟、裴楷、和嶠與其的關係。"
    },
    {
      "anchor": "貴勝年少若和裴王之徒並共宗詠",
      "question": "『和裴王』指和嶠、裴楷、王濟，但『宗詠』一詞含義不明，且此句與後文謠言的關係需釐清。",
      "why_unclear": "『宗詠』或為『宗仰詠歎』，但正文未說明他們具體詠歎什麼，是詠山濤之德，還是詠其選官之事？",
      "clues": "劉注引王隱晉書載潘岳作謠，竹林七賢論言『濤之處選，非望路絕』，暗示山濤選官公正，故為貴勝所宗。余嘉錫箋疏引李慈銘說，指出『宗』字景宋本作『言』，版本有異。",
      "impact": "若確定『宗詠』的對象與含義，可判斷此句是讚美山濤還是諷刺，進而影響對謠言性質的理解。"
    },
    {
      "anchor": "閣東有大牛和嶠鞅裴楷鞦王濟剔嬲不得休",
      "question": "謠言以『大牛』比喻山濤，但『鞅』『鞦』『剔嬲』的具體比喻義不明，且謠言作者有潘岳、潘尼兩說。",
      "why_unclear": "正文僅錄謠言，未解釋比喻；『剔嬲』一詞罕見，含義需考證。作者兩說並存，影響對謠言背景的判斷。",
      "clues": "劉注引王隱晉書作『王濟鞅，裴楷鞦，和嶠刺促不得休』，又引竹林七賢論；余嘉錫箋疏引惠士奇說，以車牛之具解釋鞅、鞦，並引黃生說釋『剔嬲』為擾亂。程炎震考證潘岳、潘尼任職時間，認為潘尼不及濤時。",
      "impact": "若明確比喻義與作者，可揭示謠言是諷刺山濤受制於人，還是讚美其選官得人，並判斷潘岳與山濤的關係。"
    }
  ],
  "commentary_issues": [
    {
      "note_id": "J08",
      "issue": "余嘉錫考證『冤句』當作『宛句』，引元和姓纂，但與晉書本傳異文，涉及地名正誤。",
      "detail": "劉注引虞預晉書作『宛句令』，余嘉錫據史地志認為『宛』非，當作『冤』，但未說明版本依據，需進一步核查。"
    },
    {
      "note_id": "J10",
      "issue": "余嘉錫引李慈銘說，質疑虞預晉書所載山濤宗人預言的真實性，認為是傅會之辭。",
      "detail": "李慈銘指出『景、文』為司馬師、司馬昭諡號，對父稱子諡不合禮法；余嘉錫推算年齡，認為預言不可信。此涉及虞預晉書的史料價值。"
    },
    {
      "note_id": "J07",
      "issue": "余嘉錫箋疏中校勘記提到『言』景宋本作『宗』，『最』景宋本作『勖』，涉及版本異文。",
      "detail": "正文『並共宗詠』之『宗』，景宋本作『言』；劉注『祖最』之『最』，景宋本作『勖』。異文影響文意理解，需考辨版本源流。"
    }
  ],
  "person_connections": [
    {
      "person_a": "山濤",
      "person_b": "和嶠",
      "connection": "同朝為官，和嶠為中書令，山濤掌選，謠言中並列。",
      "evidence": "正文謠言『和嶠鞅』；余嘉錫箋疏引程炎震說，和嶠時為中書令。"
    },
    {
      "person_a": "山濤",
      "person_b": "裴楷",
      "connection": "同朝為官，裴楷為侍中，謠言中並列。",
      "evidence": "正文謠言『裴楷鞦』；余嘉錫箋疏引程炎震說，裴楷時為侍中。"
    },
    {
      "person_a": "山濤",
      "person_b": "王濟",
      "connection": "同朝為官，王濟為侍中，謠言中並列。",
      "evidence": "正文謠言『王濟剔嬲不得休』；余嘉錫箋疏引程炎震說，王濟時為侍中。"
    },
    {
      "person_a": "潘岳",
      "person_b": "山濤",
      "connection": "潘岳內非山濤，作謠諷刺。",
      "evidence": "劉注引王隱晉書：『初，濤領吏部，潘岳內非之，密為作謠。』"
    }
  ],
  "appraisals": [
    {
      "person": "山濤",
      "appraisal": "器重朝望",
      "source": "正文"
    },
    {
      "person": "山濤",
      "appraisal": "濤之處選，非望路絕",
      "source": "竹林七賢論，見劉注"
    },
    {
      "person": "山濤",
      "appraisal": "少有器量，宿士猶不慢之",
      "source": "虞預晉書，見劉注"
    },
    {
      "person": "潘尼",
      "appraisal": "少有清才，文詞溫雅",
      "source": "文士傳，見劉注"
    }
  ]
}

